problems.optimalSolution:
function copyRandomList(head) {
  if (!head || head.length === 0) return [];
  function Node(val, next, random) {
    this.val = val;
    this.next = next || null;
    this.random = random || null;
  }
  const nodes = head.map(([val]) => new Node(val));
  for (let i = 0; i < head.length; i++) {
    if (i < head.length - 1) nodes[i].next = nodes[i + 1];
    const randIdx = head[i][1];
    if (randIdx !== null && randIdx !== undefined && randIdx >= 0) {
      nodes[i].random = nodes[randIdx];
    }
  }
  const originalHead = nodes[0];
  // Pass 1: Weave cloned nodes immediately after original nodes (A -> A' -> B -> B')
  let curr = originalHead;
  while (curr) {
    const copy = new Node(curr.val, curr.next, null);
    curr.next = copy;
    curr = copy.next;
  }
  // Pass 2: Assign random pointers for cloned nodes
  curr = originalHead;
  while (curr) {
    if (curr.random) {
      curr.next.random = curr.random.next;
    }
    curr = curr.next.next;
  }
  // Pass 3: Unweave the combined list to separate original and cloned list
  curr = originalHead;
  const copiedHead = originalHead.next;
  let copyCurr = copiedHead;
  while (curr) {
    curr.next = curr.next.next;
    copyCurr.next = copyCurr.next ? copyCurr.next.next : null;
    curr = curr.next;
    copyCurr = copyCurr.next;
  }
  const copyNodes = [];
  let temp = copiedHead;
  while (temp) {
    copyNodes.push(temp);
    temp = temp.next;
  }
  const result = [];
  for (const node of copyNodes) {
    const randIdx = node.random ? copyNodes.indexOf(node.random) : null;
    result.push([node.val, randIdx]);
  }
  return result;
}

