    const idx = this.keys.indexOf(key);
    if (idx !== -1) {
      this.keys.splice(idx, 1);
      this.values.splice(idx, 1);
    } else if (this.keys.length >= this.cap) {
      this.keys.shift();
      this.values.shift();
    }
    this.keys.push(key);
    this.values.push(value);
  }
}

