function insertionSortList(head) {
  const res = [...head];
  for (let i = 1; i < res.length; i++) {
    const key = res[i];
    let j = i - 1;
    while (j >= 0 && res[j] > key) {
      res[j + 1] = res[j];
      j--;
    }
    res[j + 1] = key;
  }
  return res;
}

